import os
import re
import time

# Whisper hallucination patterns — phrases generated by the model on silence,
# background noise, or very short audio clips.
_HALLUCINATION_PATTERNS = [
    re.compile(r"^\s*продолжение следует[\s…\.]*$", re.IGNORECASE),
    re.compile(r"^\s*субтитры (сделаны|добавлены|создан\w*)[\s\S]*$", re.IGNORECASE),
    re.compile(r"^\s*редактор субтитров[\s\S]*$", re.IGNORECASE),
    re.compile(r"^\s*to be continued[\s…\.]*$", re.IGNORECASE),
    re.compile(r"^\s*subtitles (by|made by|created by)[\s\S]*$", re.IGNORECASE),
    re.compile(r"^\s*thank(s| you) for watching[\s…\.]*$", re.IGNORECASE),
    re.compile(r"^\s*\[?(music|музыка|аплодисменты|applause)\]?[\s…\.]*$", re.IGNORECASE),
]


def make_client(config: dict):
    """Create and return a Groq client instance from the given config dict.

    Handles custom base_url and strips the /openai/v1 suffix if present
    (the SDK appends it automatically).
    """
    import time as _time
    from groq import Groq

    t_start = _time.time()
    client_kwargs = {"api_key": config["api_key"]}
    base_url = config.get("groq_base_url", "").strip()
    if base_url:
        if base_url.endswith("/openai/v1"):
            base_url = base_url[:-10]
        client_kwargs["base_url"] = base_url
    client = Groq(**client_kwargs)
    print(f"[Groq] client ready in {_time.time() - t_start:.3f}s")
    return client


def is_hallucination(text: str) -> bool:
    """Возвращает True, если текст является галлюцинацией Whisper."""
    if not text:
        return False
    text_stripped = text.strip()
    for pattern in _HALLUCINATION_PATTERNS:
        if pattern.match(text_stripped):
            return True
    return False

